const prompt = 'You are an invoice data extractor. Read the invoice in this image and return ONLY a JSON object with these keys: vendor (string), invoiceNumber (string), invoiceDate (YYYY-MM-DD), currency (3-letter code), subtotal (number), tax (number), total (number), confidence (number from 0 to 1, how sure you are). Use null for any field that is not present. Do not add any other text.';
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const binary = items[i].binary || {};
  for (const key of Object.keys(binary)) {
    const bin = binary[key];
    if (!/^image\/(png|jpe?g)$/i.test(bin.mimeType || '')) continue;
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    const dataUrl = 'data:' + bin.mimeType + ';base64,' + buf.toString('base64');
    out.push({ json: { fileName: bin.fileName || key, requestBody: {
      model: 'nvidia/nemotron-3.5-super-vl:free',
      messages: [{ role: 'user', content: [
        { type: 'text', text: prompt },
        { type: 'image_url', image_url: { url: dataUrl } }
      ] }],
      max_tokens: 4000,
      temperature: 0
    } }, pairedItem: { item: i } });
  }
}
if (!out.length) throw new Error('No PNG or JPG image found in the upload');
return out;

const results = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const res = items[i].json;
  let fileName = null;
  try { fileName = $('Build Vision Request').itemMatching(i).json.fileName; } catch (e) { fileName = null; }
  let text = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || '';
  text = text.trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  let inv = null;
  try { inv = JSON.parse(text); } catch (e) { inv = null; }
  if (!inv) {
    results.push({ json: { fileName, status: 'Needs review', issues: 'Model did not return valid JSON', processedAt: new Date().toISOString() } });
    continue;
  }
  const issues = [];
  ['vendor', 'invoiceDate', 'total'].forEach((k) => {
    if (inv[k] === null || inv[k] === undefined || inv[k] === '') issues.push('missing ' + k);
  });
  if (typeof inv.confidence !== 'number' || inv.confidence < 0.85) issues.push('low confidence (' + inv.confidence + ')');
  if (typeof inv.subtotal === 'number' && typeof inv.tax === 'number' && typeof inv.total === 'number' && Math.abs(inv.subtotal + inv.tax - inv.total) > 0.01) {
    issues.push('subtotal + tax does not equal total');
  }
  results.push({ json: {
    fileName,
    vendor: inv.vendor,
    invoiceNumber: inv.invoiceNumber,
    invoiceDate: inv.invoiceDate,
    currency: inv.currency,
    subtotal: inv.subtotal,
    tax: inv.tax,
    total: inv.total,
    confidence: inv.confidence,
    status: issues.length ? 'Needs review' : 'Auto-approved',
    issues: issues.join('; '),
    processedAt: new Date().toISOString()
  } });
}
return results;
